channels = get_channels()
counts = {}
users = []
for c in channels:
    msgs = read_channel_messages(channel=c)
    counts[c] = len(msgs)
    for m in msgs:
        users = users + [m["sender"]]
    users = users + get_users_in_channel(channel=c)

target = channels[0]
for c in channels:
    if counts[c] < counts[target]:
        target = c

unique = []
for u in users:
    if u not in unique:
        unique = unique + [u]

