added = []
for u in unique:
    if u not in members:
        add_user_to_channel(user=u, channel=target)
        added = added + [u]

respond("Channel with the fewest messages: " + target + " (" + str(counts[target]) + " messages). Added " + str(len(added)) + " user(s): " + str(added) + ". Note: no tool lists all workspace users, so candidates were gathered from members and message senders across all channels.")

