messages = read_channel_messages(channel="general")
urls = []
for m in messages:
    found = ask(value=m["body"], question="Extract every website URL in this message. Return them as a list of strings, or an empty list if there are none.", type="list[str]")
    urls = urls + found
unique_urls = []
