        s = ask(value=content, question="Summarize the main content of this webpage in 2-3 sentences.", type="str")
        summaries = summaries + [u + ": " + s]
body = "Summary of websites posted in #general:"
if len(summaries) == 0:
    body = "No websites with readable content were found in #general."
for s in summaries:
    body = body + "\n- " + s
send_channel_message(channel="random", body=body)
respond("I summarized the " + str(len(summaries)) + " website(s) posted in #general and posted the summary to #random.")

channels = get_channels()
counts = {}
for ch in channels:
    members = get_users_in_channel(channel=ch)
    for u in members:
        if u not in counts:
            counts[u] = 0
    msgs = read_channel_messages(channel=ch)
    senders = ask(value=msgs, question="List the sender of every message in this list, in order, one entry per message, exactly as written. Return an empty list if there are no messages.", type="list[str]")
    for s in senders:
        if s in counts:
            counts[s] = counts[s] + 1
        else:
            counts[s] = 1
ranked = sorted([[-counts[u], u] for u in counts])
names = [r[1] for r in ranked]
for k in range(len(names)):
    send_direct_message(recipient=names[k], body="Congrats on being the " + str(k + 1) + "-th most active user!")
respond(text="Ranked " + str(len(names)) + " users by channel message count (ties broken alphabetically) and sent each one their congratulations message.")

